// PersonalScribeLogoView.swift
// Vector-accurate quill logo for PersonalScribe — derived from the master logo SVG trace.
// Replaces the hand-coded Path approximation in the existing PersonalScribeLogoView.
//
// Usage:
//   PersonalScribeLogoView(color: Color(red: 0.831, green: 0.816, blue: 0.784))  // champagne
//   PersonalScribeLogoView(color: .white)   // for menu bar / template contexts
//
// The paths are normalised to a 2048x2048 SVG canvas and scale cleanly
// with .frame(width:height:) and .aspectRatio(1, contentMode: .fit).
//
// Source: seshat_quill.svg — vtracer spline trace of master quill logo PNG

import SwiftUI

public struct PersonalScribeLogoView: View {
    public var color: Color

    /// Default to the dark palette's `brandChampagne` — RGB
    /// (0.831, 0.816, 0.784) matches `#D4D0C8` in
    /// `PersonalScribeTheme.Palette.dark.brandChampagne`. Callers should
    /// still pass a scheme-aware tint where palette selection matters
    /// (e.g. `palette.brandChampagne` from the current environment).
    public init(color: Color = PersonalScribeTheme.Palette.dark.brandChampagne) {
        self.color = color
    }

    public var body: some View {
        GeometryReader { geo in
            let size = min(geo.size.width, geo.size.height)
            QuillShape()
                .fill(color)
                .frame(width: size, height: size)
        }
        .aspectRatio(1, contentMode: .fit)
    }
}

// MARK: - Shape

struct QuillShape: Shape {
    func path(in rect: CGRect) -> Path {
        // Scale from SVG 2048x2048 canvas to the given rect
        let scaleX = rect.width  / 2048.0
        let scaleY = rect.height / 2048.0

        var combined = Path()

        // Path 0 — main feather body (SVG translate 1921, 127)
        var p0 = Path(svgPath: _quillPath0)
        p0 = p0.applying(CGAffineTransform(translationX: 1921, y: 127))
        combined.addPath(p0)

        // Path 1 — inner feather / waveform region (SVG translate 978, 747)
        var p1 = Path(svgPath: _quillPath1)
        p1 = p1.applying(CGAffineTransform(translationX: 978, y: 747))
        combined.addPath(p1)

        // Path 2 — pen nib (SVG translate 547, 929)
        var p2 = Path(svgPath: _quillPath2)
        p2 = p2.applying(CGAffineTransform(translationX: 547, y: 929))
        combined.addPath(p2)

        // Scale entire shape to fit the target rect
        let transform = CGAffineTransform(scaleX: scaleX, y: scaleY)
            .translatedBy(x: rect.minX / scaleX, y: rect.minY / scaleY)
        return combined.applying(transform)
    }
}

// MARK: - Minimal SVG path parser (supports M, C, Z — vtracer spline output)

extension Path {
    init(svgPath: String) {
        self.init()
        var scanner = _SVGPathScanner(svgPath)
        scanner.parse(into: &self)
    }
}

private struct _SVGPathScanner {
    let data: [Character]
    var pos: Int = 0

    init(_ s: String) { data = Array(s) }

    mutating func parse(into path: inout Path) {
        while pos < data.count {
            skipWS()
            guard pos < data.count else { break }
            let cmd = data[pos]; pos += 1
            switch cmd {
            case "M":
                let x = nextFloat(), y = nextFloat()
                path.move(to: CGPoint(x: x, y: y))
            case "C":
                while pos < data.count, isNumStart(data[pos]) {
                    let c1x = nextFloat(), c1y = nextFloat()
                    let c2x = nextFloat(), c2y = nextFloat()
                    let ex  = nextFloat(), ey  = nextFloat()
                    path.addCurve(to: CGPoint(x: ex, y: ey),
                                  control1: CGPoint(x: c1x, y: c1y),
                                  control2: CGPoint(x: c2x, y: c2y))
                }
            case "Z", "z":
                path.closeSubpath()
            default: break
            }
        }
    }

    mutating func skipWS() {
        while pos < data.count, " \n\r\t".contains(data[pos]) { pos += 1 }
    }

    func isNumStart(_ c: Character) -> Bool { c.isNumber || c == "-" || c == "+" }

    mutating func nextFloat() -> CGFloat {
        skipWS()
        var s = ""
        if pos < data.count, (data[pos] == "-" || data[pos] == "+") { s.append(data[pos]); pos += 1 }
        while pos < data.count, data[pos].isNumber || data[pos] == "." { s.append(data[pos]); pos += 1 }
        skipWS()
        if pos < data.count, data[pos] == "," { pos += 1 }
        return CGFloat(Double(s) ?? 0)
    }
}

